-- Artículo 1: Moreno reforma electoral
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_001', 'clean_001', 'Moreno critica reforma electoral: apoyarla sería ceder al miedo', 'moreno-critica-reforma-electoral-apoyarla-seria-ceder-al-miedo', 'El dirigente nacional del PRI calificó la iniciativa como un acto cobarde y destructivo.', 'El senador y dirigente del PRI consideró que cualquier partido que respalde la reforma electoral propuesta por la presidenta solo evidenciará temor ante los cambios. El político de oposición señaló la ausencia de respaldo incluso por parte de aliados políticos en un contexto de creciente tensión legislativa.', 'POLITICA', 'Redacción', datetime('now'), 'https://www.elfinanciero.com.mx/resizer/v2/7QXLY6ZZHFCUFHXTCHTNSJMRPI.jpg?smart=true&width=1200&height=630', 'noticiasobjetivo,mexicoinformado', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 2: Trump Sheinbaum narcos
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_002', 'clean_002', 'Trump presiona para endurecer lucha contra narcos', 'trump-presiona-endurecer-lucha-contra-narcos', 'Analistas coinciden que la sucesora ha tratado de desmarcarse de su predecesor con sus acciones.', 'La mandataria estuvo acompañada por el secretario de Defensa y el almirante de la Armada. La imagen muestra a la funcionaria junto a las autoridades militares en un evento de alto nivel. Durante sus casi 17 meses de gobierno, ha intentado distanciarse de las políticas anteriores a través de sus acciones, mientras la presión estadounidense ha contribuido a este proceso.', 'NACIONAL', 'Redacción', datetime('now'), 'https://ichef.bbci.co.uk/news/1024/branded_mundo/c2bf/live/9a56bf60-11c2-11f1-9e8e-6f36bc130275.jpg', 'mexicoinformado,cbnnoticias', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 3: Cumbre caribeña
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_003', 'clean_003', 'Cumbre caribeña debate impacto de políticas estadounidenses', 'cumbre-caribena-debate-impacto-politicas-estadounidenses', 'En un encuentro de alto nivel celebrado en Saint Kitts y Nevis, líderes de diversas naciones caribeñas se congregaron para abordar temas estratégicos.', 'Los líderes políticos de la región caribeña se congregaron este martes en las islas gemelas de St. Kitts y Nevis para abordar temas de vital importancia para la zona. El encuentro, que se desarrolla en un contexto de desafíos múltiples, aborda cuestiones que van desde la cooperación económica hasta la respuesta al cambio climático, pasando por la seguridad regional y las relaciones diplomáticas con potencias globales. Analistas destacan que esta cumbre adquiere particular relevancia dado el complejo escenario geopolítico actual.', 'INTERNACIONAL', 'Redacción', datetime('now'), 'https://www.bostonherald.com/wp-content/uploads/2018/11/Herald_BridgePhoto.jpg', 'noticiasobjetivo,verticenoticias', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 4: Discurso Estado Unión Trump
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_004', 'clean_004', 'Trump pronuncia Discurso del Estado de la Unión: horario y dónde verlo', 'trump-pronuncia-discurso-estado-union-horario-donde-verlo', 'Donald Trump defenderá que el Partido Republicano es la opción idónea para conducir a Estados Unidos hacia una nueva era dorada.', 'El gobierno mexicano se mantendrá atento al discurso del Estado de la Unión que pronunciará Donald Trump, donde se anticipa que defenderá sus dos políticas más emblemáticas: su campaña antimigratoria y la implementación de aranceles. México parará oreja para el discurso donde se espera defienda sus políticas más importantes.', 'INTERNACIONAL', 'Redacción', datetime('now'), 'https://www.elfinanciero.com.mx/resizer/v2/LW7PNNCSUZGHPPAHKHNACM7I4M.jpeg?smart=true&width=1200&height=630', 'noticiasobjetivo,mexicoinformado', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 5: Red lavado Mencho
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_005', 'clean_005', 'Poderosa red de lavado del Mencho operó bajo vigilancia de élite política', 'poderosa-red-lavado-mencho-opero-bajo-vigilancia-elite-politica', 'Empresas fachada dedicadas a la construcción, ganadería, tequila, comercio de metales y joyas se usaron para lavar recursos del cártel.', 'La muerte del narcotraficante Nemesio Oseguera Cervantes, alias El Mencho, líder del Cártel Jalisco Nueva Generación, durante un operativo militar en Tapalpa, Jalisco, sigue siendo un tema de controversia. El operativo resultó en la muerte del capo y varios de sus lugartenientes. Sin embargo, algunos testigos afirman que el narcotraficante logró escapar y que su cuerpo nunca fue encontrado.', 'NACIONAL', 'Redacción', datetime('now'), 'https://mfes.b37m.ru/actualidad/public_images/2026.02/article/699ddd18e9ff71748e0b78c3.jpg', 'mexicoinformado,nodoinformativo', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 6: Musk censura Sheinbaum
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_006', 'clean_006', 'Musk acusa a Sheinbaum de censura en México', 'musk-acusa-sheinbaum-censura-mexico', 'La tensión entre la mandataria mexicana y el magnate tecnológico no es un fenómeno nuevo.', 'La mandataria mexicana Claudia Sheinbaum manifestó durante su conferencia de prensa matutina que evaluaría emprender acciones legales contra el magnate tecnológico Elon Musk, después de que el empresario insinuara que la jefa del Estado mexicano recibe instrucciones de organizaciones criminales. Esta situación surge en el contexto de una creciente tensión entre el gobierno mexicano y ciertos sectores empresariales estadounidenses.', 'NACIONAL', 'Redacción', datetime('now'), 'https://www.elfinanciero.com.mx/resizer/v2/7KPGSNIBE5APJH2DY4PGPVNHMU.png?smart=true&width=1200&height=630', 'mexicoinformado,cbnnoticias,centralmexico', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 7: Sheinbaum denuncia Musk
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_007', 'clean_007', 'Sheinbaum evalúa denunciar a Musk por declaración molesta', 'sheinbaum-evalua-denunciar-musk-declaracion-molesta', 'El magnate relacionó a su administración con el crimen organizado tras la detención del Mencho.', 'La presidenta Claudia Sheinbaum anunció este martes que su gobierno evalúa emprender acciones legales contra Elon Musk, tras las declaraciones del magnate estadounidense que vincularon a su empresa con el crimen organizado tras la detención de El Mencho. La mandataria manifestó que podría considerar demandar al multimillonario.', 'NACIONAL', 'Redacción', datetime('now'), 'https://resizer.glanacion.com/resizer/v2/-GNTJVSYLUFCNZJRPXGTV3ZZVWI.png?auth=e1d2dbcb4cb7077e1c796d1863efeb900eeaef07538f7428b538d78e686c1d29&width=1200&height=800', 'mexicoinformado,cbnnoticias', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 8: Europa caos arancelario
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_008', 'clean_008', 'Europa podría aprovechar el caos arancelario', 'europa-podria-aprovechar-caos-arancelario', 'La decisión del Tribunal Supremo de Estados Unidos ha invalidado el pilar central de la estrategia económica de la Administración Trump.', 'La decisión del Tribunal Supremo estadounidense, aprobada por una mayoría de seis votos contra tres, no solo ha invalidado el elemento fundamental de la estrategia económica de la Administración Trump, sino que además ha generado repercusiones de amplio alcance en el panorama político y económico del país.', 'ECONOMIA', 'Redacción', datetime('now'), 'https://e01-phantom-expansion.uecdn.es/a1bd3f2d14862a7c4a27addbbcd487df/crop/202x17/1840x1109/resize/1200/f/webp/assets/multimedia/imagenes/2026/02/24/17719598991818.jpg', 'mexicoinformado,reportecentralmx', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 9: Aranceles Trump Corte Suprema
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_009', 'clean_009', 'Nuevos aranceles de Trump entran en vigor tras decisión de Corte Suprema', 'nuevos-aranceles-trump-entran-vigor-tras-decision-corte-suprema', 'La administración recurrió a una estrategia legal poco convencional tras la decisión de la Corte Suprema.', 'En un contexto marcado por uno de los desafíos judiciales más significativos para la administración, este martes entró en vigencia un nuevo arancel adicional del 10% que afecta a la mayoría de los productos importados de China. La medida forma parte de la escalada en la disputa comercial entre ambas potencias económicas.', 'ECONOMIA', 'Redacción', datetime('now'), 'https://resizer.glanacion.com/resizer/v2/entra-en-vigor-en-eeuu-el-arancel-adicional-del-2TVWUMOW2VGBZOJGOQ42YOIQ64.JPG?auth=c07ae8cda72e3031462cc425ccd534c11747c384dfd7e3c823ec618e251e87a9&width=1200&height=800', 'mexicoinformado,reportecentralmx', 0, 0, 'PUBLICADO', 0, 0);

-- Artículo 10: Alcaldesa mexicana atacada
INSERT OR IGNORE INTO ARTICULOS_PARAFRASEADOS (ID, ID_ARTICULO_ORIGINAL, TITULO_PARAFRASEADO, SLUG, DESCRIPCION_PARAFRASEADA, CONTENIDO, CATEGORIA, AUTOR, FECHA_PUBLICACION, URL_IMAGEN, SITIO_DESTINO, DESTACADO, VISTAS, ESTADO, FB_REQUERIDO, ES_BREVE) VALUES ('clean_010', 'clean_010', 'Alcaldesa mexicana recibe disparos; su hijo muere en ataque', 'alcaldesa-mexicana-recibe-disparos-hijo-muere-ataque', 'Nora Alicia Biebrich fue sorprendida por un grupo de hombres armados durante su trayecto por una vía de comunicación.', 'La presidenta municipal fue atacada por un grupo de hombres armados mientras se desplazaba por una carretera. El ataque ocurrió cuando la funcionaria se trasladaba a un evento oficial. Las autoridades estatales han iniciado una investigación exhaustiva para dar con los responsables de este atentado.', 'NACIONAL', 'Redacción', datetime('now'), 'https://mfes.b37m.ru/actualidad/public_images/2026.02/article/699def7be9ff71613522059c.jpg', 'mexicoinformado,cbnnoticias,centralmexico', 0, 0, 'PUBLICADO', 0, 0);
